{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://api.dekat.id/schemas/events/booking-events.json",
  "definitions": {
    "booking_status": {
      "type": "string",
      "enum": ["pending", "confirmed", "in_progress", "completed", "cancelled", "rescheduled"]
    },
    "booking_data": {
      "type": "object",
      "required": ["id", "booking_code", "status", "service", "customer", "pricing", "scheduled_at", "created_at", "updated_at"],
      "properties": {
        "id": {"type": "string", "format": "uuid"},
        "booking_code": {"type": "string"},
        "status": {"$ref": "#/definitions/booking_status"},
        "service": {
          "type": "object",
          "required": ["id", "name", "category"],
          "properties": {
            "id": {"type": "string", "format": "uuid"},
            "name": {"type": "string"},
            "category": {"type": "string"},
            "duration_minutes": {"type": "integer", "minimum": 1}
          }
        },
        "provider": {
          "type": "object",
          "properties": {
            "id": {"type": "string", "format": "uuid"},
            "name": {"type": "string"}
          }
        },
        "staff": {
          "type": "object",
          "properties": {
            "id": {"type": "string", "format": "uuid"},
            "name": {"type": "string"}
          }
        },
        "customer": {
          "type": "object",
          "required": ["id"],
          "properties": {
            "id": {"type": "string", "format": "uuid"},
            "name": {"type": "string"},
            "phone": {"type": "string"},
            "email": {"type": "string", "format": "email"}
          }
        },
        "pricing": {
          "type": "object",
          "required": ["total_amount", "currency"],
          "properties": {
            "base_amount": {"type": "number", "minimum": 0},
            "discount_amount": {"type": "number", "minimum": 0},
            "tax_amount": {"type": "number", "minimum": 0},
            "total_amount": {"type": "number", "minimum": 0},
            "currency": {"type": "string", "default": "IDR"}
          }
        },
        "scheduled_at": {"type": "string", "format": "date-time"},
        "notes": {"type": "string"},
        "created_at": {"type": "string", "format": "date-time"},
        "updated_at": {"type": "string", "format": "date-time"},
        "cancelled_at": {"type": "string", "format": "date-time"},
        "cancellation_reason": {"type": "string"},
        "completed_at": {"type": "string", "format": "date-time"}
      }
    }
  },
  "oneOf": [
    {
      "$id": "https://api.dekat.id/schemas/events/booking.created.json",
      "description": "Emitted when a new booking is created",
      "type": "object",
      "required": ["event_id", "event_type", "event_version", "occurred_at", "producer", "tenant_id", "aggregate_type", "aggregate_id", "data"],
      "properties": {
        "event_type": {"const": "booking.created"},
        "event_version": {"const": 1},
        "aggregate_type": {"const": "booking"},
        "data": {"$ref": "#/definitions/booking_data"}
      }
    },
    {
      "$id": "https://api.dekat.id/schemas/events/booking.confirmed.json",
      "description": "Emitted when a booking is confirmed by the provider",
      "type": "object",
      "required": ["event_id", "event_type", "event_version", "occurred_at", "producer", "tenant_id", "aggregate_type", "aggregate_id", "data"],
      "properties": {
        "event_type": {"const": "booking.confirmed"},
        "event_version": {"const": 1},
        "aggregate_type": {"const": "booking"},
        "data": {"$ref": "#/definitions/booking_data"}
      }
    },
    {
      "$id": "https://api.dekat.id/schemas/events/booking.cancelled.json",
      "description": "Emitted when a booking is cancelled",
      "type": "object",
      "required": ["event_id", "event_type", "event_version", "occurred_at", "producer", "tenant_id", "aggregate_type", "aggregate_id", "data"],
      "properties": {
        "event_type": {"const": "booking.cancelled"},
        "event_version": {"const": 1},
        "aggregate_type": {"const": "booking"},
        "data": {
          "allOf": [
            {"$ref": "#/definitions/booking_data"},
            {
              "type": "object",
              "required": ["cancelled_at", "cancellation_reason"],
              "properties": {
                "cancelled_at": {"type": "string", "format": "date-time"},
                "cancellation_reason": {"type": "string"}
              }
            }
          ]
        }
      }
    },
    {
      "$id": "https://api.dekat.id/schemas/events/booking.completed.json",
      "description": "Emitted when a booking service is completed",
      "type": "object",
      "required": ["event_id", "event_type", "event_version", "occurred_at", "producer", "tenant_id", "aggregate_type", "aggregate_id", "data"],
      "properties": {
        "event_type": {"const": "booking.completed"},
        "event_version": {"const": 1},
        "aggregate_type": {"const": "booking"},
        "data": {
          "allOf": [
            {"$ref": "#/definitions/booking_data"},
            {
              "type": "object",
              "required": ["completed_at"],
              "properties": {
                "completed_at": {"type": "string", "format": "date-time"}
              }
            }
          ]
        }
      }
    },
    {
      "$id": "https://api.dekat.id/schemas/events/booking.rescheduled.json",
      "description": "Emitted when a booking is rescheduled to a new time",
      "type": "object",
      "required": ["event_id", "event_type", "event_version", "occurred_at", "producer", "tenant_id", "aggregate_type", "aggregate_id", "data"],
      "properties": {
        "event_type": {"const": "booking.rescheduled"},
        "event_version": {"const": 1},
        "aggregate_type": {"const": "booking"},
        "data": {
          "allOf": [
            {"$ref": "#/definitions/booking_data"},
            {
              "type": "object",
              "required": ["previous_scheduled_at"],
              "properties": {
                "previous_scheduled_at": {"type": "string", "format": "date-time"},
                "reschedule_reason": {"type": "string"}
              }
            }
          ]
        }
      }
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://api.dekat.id/schemas/events/payment-events.json",
  "definitions": {
    "payment_status": {
      "type": "string",
      "enum": ["pending", "processing", "paid", "failed", "refunded", "partially_refunded"]
    },
    "payment_data": {
      "type": "object",
      "required": ["id", "booking_id", "amount", "currency", "status", "created_at", "updated_at"],
      "properties": {
        "id": {"type": "string", "format": "uuid"},
        "booking_id": {"type": "string", "format": "uuid"},
        "amount": {"type": "number", "minimum": 0},
        "currency": {"type": "string", "default": "IDR"},
        "status": {"$ref": "#/definitions/payment_status"},
        "method": {"type": "string", "description": "Payment method (e.g. cash, credit_card, bank_transfer, ewallet)"},
        "gateway": {
          "type": "object",
          "properties": {
            "provider": {"type": "string", "description": "Gateway provider name (e.g. midtrans, xendit, manual)"},
            "reference_id": {"type": "string", "description": "External gateway transaction ID"},
            "response_code": {"type": "string"},
            "response_message": {"type": "string"}
          }
        },
        "refund": {
          "type": "object",
          "properties": {
            "amount": {"type": "number", "minimum": 0},
            "reason": {"type": "string"},
            "refunded_at": {"type": "string", "format": "date-time"}
          }
        },
        "metadata": {"type": "object"},
        "created_at": {"type": "string", "format": "date-time"},
        "updated_at": {"type": "string", "format": "date-time"},
        "paid_at": {"type": "string", "format": "date-time"},
        "failed_at": {"type": "string", "format": "date-time"},
        "failure_reason": {"type": "string"}
      }
    }
  },
  "oneOf": [
    {
      "$id": "https://api.dekat.id/schemas/events/payment.created.json",
      "description": "Emitted when a payment record is created for a booking",
      "type": "object",
      "required": ["event_id", "event_type", "event_version", "occurred_at", "producer", "tenant_id", "aggregate_type", "aggregate_id", "data"],
      "properties": {
        "event_type": {"const": "payment.created"},
        "event_version": {"const": 1},
        "aggregate_type": {"const": "payment"},
        "data": {"$ref": "#/definitions/payment_data"}
      }
    },
    {
      "$id": "https://api.dekat.id/schemas/events/payment.paid.json",
      "description": "Emitted when a payment is successfully received",
      "type": "object",
      "required": ["event_id", "event_type", "event_version", "occurred_at", "producer", "tenant_id", "aggregate_type", "aggregate_id", "data"],
      "properties": {
        "event_type": {"const": "payment.paid"},
        "event_version": {"const": 1},
        "aggregate_type": {"const": "payment"},
        "data": {
          "allOf": [
            {"$ref": "#/definitions/payment_data"},
            {
              "type": "object",
              "required": ["paid_at", "gateway"],
              "properties": {
                "paid_at": {"type": "string", "format": "date-time"},
                "gateway": {
                  "type": "object",
                  "required": ["provider", "reference_id"],
                  "properties": {
                    "provider": {"type": "string"},
                    "reference_id": {"type": "string"}
                  }
                }
              }
            }
          ]
        }
      }
    },
    {
      "$id": "https://api.dekat.id/schemas/events/payment.failed.json",
      "description": "Emitted when a payment attempt fails",
      "type": "object",
      "required": ["event_id", "event_type", "event_version", "occurred_at", "producer", "tenant_id", "aggregate_type", "aggregate_id", "data"],
      "properties": {
        "event_type": {"const": "payment.failed"},
        "event_version": {"const": 1},
        "aggregate_type": {"const": "payment"},
        "data": {
          "allOf": [
            {"$ref": "#/definitions/payment_data"},
            {
              "type": "object",
              "required": ["failed_at", "failure_reason"],
              "properties": {
                "failed_at": {"type": "string", "format": "date-time"},
                "failure_reason": {"type": "string"},
                "gateway": {
                  "type": "object",
                  "properties": {
                    "provider": {"type": "string"},
                    "reference_id": {"type": "string"},
                    "response_code": {"type": "string"},
                    "response_message": {"type": "string"}
                  }
                }
              }
            }
          ]
        }
      }
    },
    {
      "$id": "https://api.dekat.id/schemas/events/payment.refunded.json",
      "description": "Emitted when a payment is refunded (full or partial)",
      "type": "object",
      "required": ["event_id", "event_type", "event_version", "occurred_at", "producer", "tenant_id", "aggregate_type", "aggregate_id", "data"],
      "properties": {
        "event_type": {"const": "payment.refunded"},
        "event_version": {"const": 1},
        "aggregate_type": {"const": "payment"},
        "data": {
          "allOf": [
            {"$ref": "#/definitions/payment_data"},
            {
              "type": "object",
              "required": ["refund"],
              "properties": {
                "refund": {
                  "type": "object",
                  "required": ["amount", "reason", "refunded_at"],
                  "properties": {
                    "amount": {"type": "number", "minimum": 0},
                    "reason": {"type": "string"},
                    "refunded_at": {"type": "string", "format": "date-time"}
                  }
                }
              }
            }
          ]
        }
      }
    }
  ]
}

import { test, expect } from '@playwright/test';

test.describe('DEKAT Web Provider - Runtime Proof', () => {
  test('login page renders correctly', async ({ page }) => {
    await page.goto('http://localhost:3001/login');
    await expect(page.locator('text=DEKAT').or(page.locator('text=Provider'))).toBeVisible();
    await expect(page.locator('input[type="email"]').or(page.locator('input[name="email"]'))).toBeVisible();
    await expect(page.locator('input[type="password"]').or(page.locator('input[name="password"]'))).toBeVisible();
  });

test('dashboard redirects to login when not authenticated', async ({ page }) => {
    await page.goto('http://localhost:3001/dashboard');
    await expect(page).toHaveURL(/.*login/);
  });

test('login form has email and password fields', async ({ page }) => {
    await page.goto('http://localhost:3001/login');
    const emailInput = page.locator('input[type="email"]').or(page.locator('input[name="email"]'));
    const passwordInput = page.locator('input[type="password"]').or(page.locator('input[name="password"]'));
    await expect(emailInput).toBeVisible();
    await expect(passwordInput).toBeVisible();
  });

test('login form has submit button', async ({ page }) => {
    await page.goto('http://localhost:3001/login');
    await expect(page.locator('button[type="submit"]').or(page.locator('button:has-text("Masuk")'))).toBeVisible();
  });
});

import { test, expect } from '@playwright/test';

test.describe('DEKAT Web Public - Runtime Proof', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the app
    await page.goto('/');
  });

test('homepage loads with DEKAT branding', async ({ page }) => {
    await expect(page.locator('text=DEKAT').first()).toBeVisible();
    await expect(page.locator('text=Booking Platform')).toBeVisible();
  });

test('homepage shows categories section', async ({ page }) => {
    // Categories section should be present
    await expect(page.locator('text=Kategori').or(page.locator('text=category'))).toBeVisible();
  });

test('homepage shows featured providers section', async ({ page }) => {
    // Featured providers section should be present
    await expect(page.locator('text=Featured').or(page.locator('text=Unggulan'))).toBeVisible();
  });

test('navigation to search page works', async ({ page }) => {
    await page.click('text=Cari Layanan');
    await expect(page).toHaveURL(/.*search/);
  });

test('navigation to login page works', async ({ page }) => {
    await page.click('text=Masuk');
    await expect(page).toHaveURL(/.*login/);
  });

test('navigation to register page works', async ({ page }) => {
    await page.click('text=Daftar');
    await expect(page).toHaveURL(/.*register/);
  });

test('search page renders with filters', async ({ page }) => {
    await page.goto('/search');
    await expect(page.locator('input[type="text"]').first()).toBeVisible();
  });

test('login page renders form fields', async ({ page }) => {
    await page.goto('/login');
    await expect(page.locator('input[type="email"]').or(page.locator('input[name="email"]'))).toBeVisible();
    await expect(page.locator('input[type="password"]').or(page.locator('input[name="password"]'))).toBeVisible();
  });

test('register page renders form fields', async ({ page }) => {
    await page.goto('/register');
    await expect(page.locator('input').first()).toBeVisible();
  });

test('provider page shows not found for invalid slug', async ({ page }) => {
    await page.goto('/provider/invalid-slug-12345');
    await expect(page.locator('text=tidak ditemukan').or(page.locator('text=not found'))).toBeVisible();
  });

test('booking page shows for valid provider ID format', async ({ page }) => {
    await page.goto('/booking/00000000-0000-0000-0000-000000000001');
    // Should render the booking wizard (step 1)
    await expect(page.locator('text=Layanan').or(page.locator('text=Service'))).toBeVisible();
  });

test('footer renders with copyright', async ({ page }) => {
    const year = new Date().getFullYear().toString();
    await expect(page.locator(`text=${year}`)).toBeVisible();
  });

test('header has search input on desktop', async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 720 });
    const searchInputs = page.locator('input[placeholder*="Cari"]');
    await expect(searchInputs.first()).toBeVisible();
  });
});
